/* One Design System, Three Products, Any Brand — prototype: the page wears a brand; evidence, rendered from one set of tokens.
   The invented brand's scales follow the real system's rules (fixed lightness per step); the lightness chart uses
   the real system's lightness values, which carry no brand. */
(() => {
  "use strict";

  /* ---------- tokens (invented brand; generated by gen.py, every text pairing ≥ 4.5:1) ---------- */
  const SCALES = {"light": {"brand": {"50": "#dffcfd", "200": "#5ddae0", "500": "#00a0a6", "600": "#007176", "700": "#005f63"}, "blue": {"50": "#eff6ff", "200": "#9cc7ff", "500": "#1f8aff", "600": "#0061be", "700": "#0051a0"}, "green": {"50": "#e8fbea", "200": "#92d89c", "500": "#00a943", "600": "#00782d", "700": "#006425"}, "red": {"50": "#fff2f0", "200": "#ffaba3", "500": "#ed4a49", "600": "#bb061e", "700": "#9b0f1b"}, "purple": {"50": "#f9f2ff", "200": "#dab0fa", "500": "#b161e5", "600": "#8632b6", "700": "#6f2c96"}, "amber": {"50": "#fff3e4", "200": "#ffce8a", "500": "#eba000", "600": "#956300", "700": "#7e5400"}}, "dark": {"brand": {"50": "#001b1c", "200": "#003b3e", "500": "#00999f", "600": "#00c9d1", "700": "#7edde2"}, "blue": {"50": "#05162c", "200": "#183356", "500": "#0c84fa", "600": "#79b4ff", "700": "#a7ceff"}, "green": {"50": "#031c08", "200": "#153c1d", "500": "#00a240", "600": "#6dc97d", "700": "#a3dbaa"}, "red": {"50": "#290b0a", "200": "#512320", "500": "#e64343", "600": "#fe8b83", "700": "#ffb5ae"}, "purple": {"50": "#1d0f27", "200": "#3e284d", "500": "#ab5ade", "600": "#cc97f3", "700": "#ddbbf7"}, "amber": {"50": "#211300", "200": "#472d00", "500": "#c38400", "600": "#e7af5c", "700": "#f4c98e"}}};
  const NEUTRAL = {"light": {"background": "#ffffff", "card": "#ffffff", "foreground": "#09090b", "muted": "#f4f4f5", "muted-foreground": "#71717b", "border": "#e4e4e7", "input": "#f4f4f5"}, "dark": {"background": "#09090b", "card": "#18181b", "foreground": "#fafafa", "muted": "#27272a", "muted-foreground": "#9f9fa9", "border": "#2d2d31", "input": "#1f1f23"}};
  const HUES = [["brand", "Brand", "primary"], ["blue", "Blue", "info"], ["green", "Green", "success"], ["red", "Red", "destructive"], ["purple", "Purple", "categorical"], ["amber", "Amber", "warning"]];
  const STEPS = [["50", "Surface"], ["200", "Border"], ["500", "Charts, icons"], ["600", "Text on white"], ["700", "Text on a tint"]];
  /* the real system's lightness per step (light mode); hue-free, so safe to show */
  const REAL_L = {
    "50": { brand: .97, blue: .97, green: .97, red: .97, purple: .97, amber: .97 },
    "200": { brand: .82, blue: .82, green: .82, red: .82, purple: .82, amber: .88 },
    "500": { blue: .623, green: .64, red: .65, purple: .63, amber: .76 },
    "600": { brand: .50, blue: .50, green: .50, red: .52, purple: .50, amber: .54 },
    "700": { brand: .44, blue: .44, green: .44, red: .45, purple: .44, amber: .48 },
  };

  /* ---------- colour maths: OKLab/OKLCH ↔ sRGB, WCAG 2 contrast ---------- */
  const toLin = (v) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4);
  const toGam = (v) => (v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055);
  function hexToRgb(h) { h = h.replace("#", ""); if (h.length === 3) h = [...h].map((x) => x + x).join(""); return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16) / 255); }
  function rgbToHex(rgb) { return "#" + rgb.map((v) => Math.round(Math.min(1, Math.max(0, v)) * 255).toString(16).padStart(2, "0")).join(""); }
  function rgbToOklab([r, g, b]) {
    [r, g, b] = [r, g, b].map(toLin);
    const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
    const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
    const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
    return [0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s, 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s, 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s];
  }
  function oklabToLin([L, a, b]) {
    const l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3, m = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3, s = (L - 0.0894841775 * a - 1.291485548 * b) ** 3;
    return [4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s, -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s, -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s];
  }
  const lch = (lab) => ({ l: lab[0], c: Math.hypot(lab[1], lab[2]), h: ((Math.atan2(lab[2], lab[1]) * 180) / Math.PI + 360) % 360 });
  const lab = ({ l, c, h }) => [l, c * Math.cos((h * Math.PI) / 180), c * Math.sin((h * Math.PI) / 180)];
  const inside = (v) => v.every((x) => x >= -1e-4 && x <= 1 + 1e-4);
  function inGamut(c) { if (inside(oklabToLin(lab(c)))) return c; let lo = 0, hi = c.c; for (let i = 0; i < 20; i++) { const mid = (lo + hi) / 2; if (inside(oklabToLin(lab({ ...c, c: mid })))) lo = mid; else hi = mid; } return { ...c, c: lo }; }
  const hexToLch = (h) => lch(rgbToOklab(hexToRgb(h)));
  const lchToHex = (c) => rgbToHex(oklabToLin(lab(inGamut(c))).map(toGam));
  function lum(h) { const [r, g, b] = hexToRgb(h).map(toLin); return 0.2126 * r + 0.7152 * g + 0.0722 * b; }
  function ratio(a, b) { const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); }
  function mix(a, b, t) { const A = rgbToOklab(hexToRgb(a)), B = rgbToOklab(hexToRgb(b)); return rgbToHex(oklabToLin(A.map((v, i) => v * t + B[i] * (1 - t))).map(toGam)); }

  /* ---------- the rule: the customer chooses the hue, the system chooses the lightness ---------- */
  const AA = 4.6; // a little over 4.5, so values still pass after rounding
  const NEAR_WHITE = "#fafafa", NEAR_BLACK = "#09090b";
  function readableOn(brand, surfaces, dir) {
    const ok = (l) => surfaces.every((s) => ratio(lchToHex({ ...brand, l }), s) >= AA);
    if (ok(brand.l)) return lchToHex(brand);
    let good = dir === "darker" ? 0 : 1, bad = brand.l;
    for (let i = 0; i < 24; i++) { const mid = (good + bad) / 2; if (ok(mid)) good = mid; else bad = mid; }
    return lchToHex({ ...brand, l: good });
  }
  const pickOn = (fill) => (ratio(NEAR_WHITE, fill) >= AA || ratio(NEAR_WHITE, fill) >= ratio(NEAR_BLACK, fill) ? NEAR_WHITE : NEAR_BLACK);

  /** All the tokens a panel needs, for one colour, one mode and one rule. */
  function theme(hex, mode, rule = "derived") {
    const n = NEUTRAL[mode], s = SCALES[mode], dark = mode === "dark";
    const b = hexToLch(hex);
    const t = {
      "--bg": n.background, "--card": n.card, "--fg": n.foreground, "--muted": n.muted, "--muted-fg": n["muted-foreground"],
      "--border": n.border, "--input": n.border, "--input-bg": n.input,
      "--primary": hex,
    };
    if (rule === "derived") {
      const cont = lchToHex({ l: dark ? 0.2 : 0.97, c: Math.min(b.c, dark ? 0.05 : 0.03), h: b.h });
      Object.assign(t, {
        "--primary-fg": pickOn(hex),
        "--primary-text": readableOn(b, dark ? [n.background, n.card] : [n.background, n.card], dark ? "lighter" : "darker"),
        "--primary-container": cont,
        "--primary-container-fg": readableOn(b, [cont], dark ? "lighter" : "darker"),
        "--primary-border": lchToHex({ l: dark ? 0.32 : 0.82, c: Math.min(b.c, dark ? 0.07 : 0.11), h: b.h }),
      });
    } else {
      /* the first version: the colour written straight into the primary tokens */
      Object.assign(t, {
        "--primary-fg": NEAR_WHITE,
        "--primary-text": hex,
        "--primary-container": mix(hex, n.background, 0.18),
        "--primary-container-fg": hex,
        "--primary-border": mix(hex, n.border, 0.35),
      });
    }
    t["--ring"] = t["--primary-text"];
    const roles = { success: "green", warning: "amber", destructive: "red", info: "blue", categorical: "purple" };
    for (const [role, hue] of Object.entries(roles)) {
      t[`--${role}`] = s[hue]["500"];
      t[`--${role}-container`] = s[hue]["50"];
      t[`--${role}-container-fg`] = s[hue]["700"];
      t[`--${role}-border`] = s[hue]["200"];
      t[`--${role}-text`] = s[hue]["600"];
    }
    t["--destructive"] = dark ? s.red["600"] : s.red["600"];
    return t;
  }
  const apply = (el, t) => { for (const [k, v] of Object.entries(t)) el.style.setProperty(k, v); };
  const chip = (r) => `<span class="ds-ratio ${r >= 4.5 ? "is-pass" : "is-fail"}">${r >= 4.5 ? "✓" : "✕"} ${r.toFixed(2)}:1</span>`;
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);

  const ICON_WARN = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M8 2.5 14 13H2z" stroke-linejoin="round"/><path d="M8 6.5v3M8 11.3v.2" stroke-linecap="round"/></svg>';

  function appHTML(c) {
    return `
      <div class="tp-head">
        <span class="tp-logo" aria-hidden="true">${c.mark}</span><b>Deliveries</b>
        <nav class="tp-tabs" aria-label="Example navigation"><span class="is-on">Today<span data-r="tab"></span></span><span>Routes</span><span>Drivers</span><span>Reports</span></nav>
        <span class="tp-user" aria-hidden="true"></span>
      </div>
      <div class="tp-body">
        <section class="tp-card" aria-label="Today's runs">
          <div class="tp-actions"><h4>Today's runs</h4><div><button type="button" class="ui-btn is-outline">Export</button><button type="button" class="ui-btn is-primary">New run<span data-r="btn"></span></button></div></div>
          <div class="tp-filters">
            <label class="ui-field"><span class="sr-only">Search runs</span><input class="ui-input" type="search" placeholder="Search runs" aria-label="Search runs"></label>
            <label class="ui-field"><span class="sr-only">Depot</span><select class="ui-select" aria-label="Depot"><option>All depots</option><option>North depot</option><option>Harbour depot</option></select></label>
          </div>
          <ul class="tp-rows">
            <li><b>Run 4821</b><span class="ui-badge r-success">Delivered<span data-r="ok"></span></span><small>14 stops · North depot</small></li>
            <li><b>Run 4822</b><span class="ui-badge r-warning">Delayed</span><small>9 stops · Harbour depot</small></li>
            <li><b>Run 4823</b><span class="ui-badge r-info">On the road</span><small>11 stops · North depot</small></li>
            <li><b>Run 4824</b><span class="ui-badge r-destructive">Failed</span><small>3 stops · Harbour depot</small></li>
          </ul>
          <div class="tp-actions"><div class="ui-pages" aria-label="Pages"><span class="is-on">1</span><span>2</span><span>3</span><span>…</span><span>10</span></div><a class="ui-link" href="#work-panel">View all runs</a><span data-r="link"></span></div>
        </section>
        <section class="tp-card" aria-label="Driver">
          <h4>Run 4822</h4>
          <p>Two stops are behind schedule.<span data-r="muted"></span></p>
          <div class="ui-alert r-warning" role="note">${ICON_WARN}<span><strong>Delayed</strong> by 25 minutes at Harbour depot.</span></div>
          <label class="ui-field"><span>Note for the driver <b>*</b></span><small>Shown on their phone at the next stop.</small><input class="ui-input is-error" value="" placeholder="Write a note"><small class="ui-err">A note is required.</small></label>
          <div class="tp-actions"><div><button type="button" class="ui-btn is-ghost">Cancel</button><button type="button" class="ui-btn is-primary">Send</button></div></div>
        </section>
      </div>`;
  }

  function fillRatios(root, t) {
    const set = (k, r) => { const el = root.querySelector(`[data-r="${k}"]`); if (el) el.innerHTML = chip(r); };
    set("btn", ratio(t["--primary-fg"], t["--primary"]));
    set("link", ratio(t["--primary-text"], t["--card"]));
    set("tab", ratio(t["--primary-container-fg"], t["--primary-container"]));
    set("ok", ratio(t["--success-container-fg"], t["--success-container"]));
    set("muted", ratio(t["--muted-fg"], t["--card"]));
  }

  /* ---------- the page wears a brand: one colour in, the case file's palette out ---------- */
  const INK = "#1c1b19", PAPER = "#fbfaf7", PAPER_D = "#1f1e1c", INSET_D = "#282624";
  const pickPage = (f) => (ratio(NEAR_WHITE, f) >= AA ? NEAR_WHITE : INK);
  const tone = (b, l, c) => lchToHex({ l, c: Math.min(b.c, c), h: b.h });
  function secondOn(on, field) { for (const t of [0.74, 0.8, 0.86, 0.92]) { const m = mix(on, field, t); if (ratio(m, field) >= AA) return m; } return on; }
  function pagePalette(hex) {
    const b = hexToLch(hex);
    const L = {}, D = {};
    // light page
    L.field = hex; L["on-field"] = pickPage(hex); L["on-field-2"] = secondOn(L["on-field"], hex);
    const pale = L["on-field"] === INK;
    L.accent = pale ? INK : readableOn(b, [PAPER, "#ffffff"], "darker");
    L["accent-strong"] = L.accent; L["on-accent"] = pale ? hex : pickOn(L.accent);
    L["ds-mark"] = hex; L["ds-mark-ink"] = pickPage(hex);
    L["accent-2"] = tone(b, 0.94, 0.05); L["accent-tint"] = tone(b, 0.975, 0.03);
    const dk = tone(b, 0.19, 0.016);
    Object.assign(L, { dark: dk, "on-dark": "#f5f3ee", "on-dark-body": "#d4d0c7", "on-dark-2": "#a29e95", "dark-rule": tone(b, 0.27, 0.016), "dark-line": tone(b, 0.42, 0.02), "dark-inset": tone(b, 0.23, 0.016) });
    L["accent-on-dark"] = ratio(hex, dk) >= AA ? hex : readableOn(b, [dk], "lighter");
    // dark page: fields deeper or lifted just enough to sit on the dark studio; text by the same rule
    const fd = b.l > 0.8 ? lchToHex({ ...b, l: 0.8 }) : b.l < 0.36 ? lchToHex({ ...b, l: 0.4 }) : hex;
    D.field = fd; D["on-field"] = pickPage(fd); D["on-field-2"] = secondOn(D["on-field"], fd);
    D.accent = ratio(hex, PAPER_D) >= AA && ratio(hex, INSET_D) >= AA ? hex : readableOn(b, [PAPER_D, INSET_D], "lighter");
    D["accent-strong"] = D.accent; D["on-accent"] = pickOn(D.accent);
    D["ds-mark"] = D.accent; D["ds-mark-ink"] = pickPage(D.accent);
    D["accent-2"] = tone(b, 0.27, 0.04); D["accent-tint"] = tone(b, 0.25, 0.035);
    const dd = tone(b, 0.15, 0.014);
    Object.assign(D, { dark: dd, "dark-rule": tone(b, 0.23, 0.025), "dark-line": tone(b, 0.38, 0.03), "dark-inset": tone(b, 0.2, 0.025) });
    D["accent-on-dark"] = ratio(hex, dd) >= AA ? hex : readableOn(b, [dd], "lighter");
    return { L, D };
  }
  const vars = (o) => Object.entries(o).map(([k, v]) => `--${k}:${v}`).join(";");
  const sheet = document.getElementById("ds-palette");

  /* ---------- customers (invented) ---------- */
  const CUSTOMERS = [
    { id: "courier", name: "Courier", colour: "#f2c94c", font: '"Archivo", var(--sans)', r: "0", btn: "0", mark: "C" },
    { id: "platform", name: "Platform", colour: "#0c5c63", font: '"Geist", var(--sans)', r: "0.5rem", btn: "0.5rem", mark: "P" },
    { id: "grocer", name: "Grocer", colour: "#2e7d3a", font: '"Fraunces", Georgia, serif', r: "0.75rem", btn: "999px", mark: "G" },
    { id: "bank", name: "Bank", colour: "#1d2b5c", font: '"IBM Plex Sans", var(--sans)', r: "0.375rem", btn: "0.75rem", mark: "B" },
  ];
  const state = { id: "courier", own: "#e85d9a", mode: "light", ratios: false };
  const current = () => (state.id === "own" ? { ...CUSTOMERS[1], id: "own", name: "Your colour", colour: state.own, mark: "Y" } : CUSTOMERS.find((c) => c.id === state.id));
  const listeners = [];
  function setCustomer(id) {
    state.id = id;
    const c = current();
    const { L, D } = pagePalette(c.colour);
    const extra = `--ds-btn-font:${c.font};--ds-btn-r:${c.btn}`;
    sheet.textContent = `[data-palette="design-system"]{${vars(L)};${extra}}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]) [data-palette="design-system"]{${vars(D)}}}
:root[data-theme="dark"] [data-palette="design-system"]{${vars(D)}}`;
    document.querySelectorAll(`input[data-cust]`).forEach((i) => (i.checked = i.value === id));
    listeners.forEach((fn) => fn(c));
  }

  /* ---------- cover: "Seen as" and the layers ---------- */
  const seen = document.getElementById("seen-as");
  if (seen) {
    seen.innerHTML = `<span>Seen as</span>` + CUSTOMERS.map((c) => `<label><input type="radio" name="seen" data-cust value="${c.id}" id="seen-${c.id}"><i class="ds-dot" style="background:${c.colour}"></i>${c.name}</label>`).join("");
    seen.addEventListener("change", (e) => { if (e.target.name === "seen") setCustomer(e.target.value); });
  }
  const layersArt = document.getElementById("cover-layers");
  if (layersArt) {
    const plane = (cx, cy, w, h) => `${cx - w / 2},${cy} ${cx},${cy - h / 2} ${cx + w / 2},${cy} ${cx},${cy + h / 2}`;
    const cx = 140, w = 210, h = 105, ys = [66, 128, 190];
    const draw = (c) => {
      layersArt.innerHTML = `<svg viewBox="0 0 400 260" role="img" aria-label="Three layers: shared, product, customer">
        <line class="rail" x1="${cx}" x2="${cx}" y1="${ys[0]}" y2="${ys[2]}"/>
        <polygon class="pl pl-shared" points="${plane(cx, ys[2], w, h)}"/>
        <polygon class="pl pl-product" points="${plane(cx, ys[1], w, h)}"/>
        <polygon class="pl pl-customer" points="${plane(cx, ys[0], w, h)}"/>
        <polygon class="btn" points="${plane(cx, ys[0], 84, 42)}"/>
        ${[["Customer", c.name, ys[0]], ["Product", "", ys[1]], ["Shared", "", ys[2]]].map(([t, n, y]) => `<line class="tick" x1="${cx + w / 2 + 6}" x2="${cx + w / 2 + 22}" y1="${y}" y2="${y}"/><text x="${cx + w / 2 + 28}" y="${y + 4}">${t}</text>${n ? `<text class="is-brand" x="${cx + w / 2 + 28}" y="${y + 22}">${esc(n)}</text>` : ""}`).join("")}
      </svg>`;
    };
    listeners.push(draw);
  }

  /* ---------- the work: the theme panel follows "Seen as" ---------- */
  const work = document.getElementById("work-panel");
  if (work) {
    work.innerHTML = `
      <div class="tp-controls">
        <div class="tp-left">
          <div class="ds-seg" role="radiogroup" aria-label="Customer">
            ${CUSTOMERS.map((c) => `<label><input type="radio" name="tp-customer" data-cust value="${c.id}" id="tp-c-${c.id}"><i class="ds-dot" style="background:${c.colour}"></i>${esc(c.name)}</label>`).join("")}
            <label class="tp-own"><input type="radio" name="tp-customer" data-cust value="own" id="tp-c-own"><span>Your colour</span></label>
          </div>
          <span class="tp-own"><input type="color" id="tp-own-colour" value="${state.own}" aria-label="Pick your own brand colour"></span>
        </div>
        <div class="tp-right">
          <div class="ds-seg" role="radiogroup" aria-label="Mode">
            <label><input type="radio" name="tp-mode" id="tp-m-light" value="light" checked>Light</label>
            <label><input type="radio" name="tp-mode" id="tp-m-dark" value="dark">Dark</label>
          </div>
          <label class="ds-check"><input type="checkbox" id="tp-ratios"> Show ratios</label>
        </div>
      </div>
      <div class="tp-app ui" id="tp-app"></div>`;
    const app = work.querySelector("#tp-app");
    const render = (c) => {
      app.innerHTML = appHTML(c);
      const t = theme(c.colour, state.mode);
      apply(app, t);
      app.style.setProperty("--font", c.font); app.style.setProperty("--r", c.r); app.style.setProperty("--btn-r", c.btn);
      app.style.colorScheme = state.mode;
      fillRatios(app, t);
      app.classList.toggle("show-ratios", state.ratios);
    };
    listeners.push(render);
    work.addEventListener("change", (e) => {
      if (e.target.name === "tp-customer") return setCustomer(e.target.value);
      if (e.target.name === "tp-mode") state.mode = e.target.value;
      if (e.target.id === "tp-ratios") state.ratios = e.target.checked;
      render(current());
    });
    work.querySelector("#tp-own-colour").addEventListener("input", (e) => { state.own = e.target.value; setCustomer("own"); });
  }

  /* ---------- 01.1: the same screen, three products ---------- */
  document.querySelectorAll("[data-mp]").forEach((el) => {
    el.innerHTML = `<div class="mp-bar"><i class="mp-logo"></i><b>Deliveries</b><span>Today</span></div>
      <div class="mp-main"><div class="mp-top"><h4>Today's runs</h4><span class="mp-btn">New run</span></div>
      <ul class="mp-list"><li><span>Run 4821</span><span class="mp-badge">On time</span></li><li><span>Run 4822</span><span class="mp-badge is-warn">Delayed</span></li><li><span>Run 4823</span><span class="mp-badge">On time</span></li><li><span>Run 4824</span><span class="mp-badge">On time</span></li></ul></div>`;
  });

  /* ---------- 01.2: the same library, rendered from code; one stage with a Figma / Code switch ---------- */
  const codeSide = document.getElementById("code-side");
  if (codeSide) {
    const brand = SCALES.light.brand["600"];
    codeSide.innerHTML = ["light", "dark"].map((mode) => `<div class="ds-f2c-pane ui" data-mode="${mode}">
        <span>${mode === "light" ? "Light" : "Dark"}</span>
        <div class="ds-f2c-row"><span class="ui-btn is-primary">Settings</span><span class="ui-btn is-outline">Settings</span><span class="ui-btn is-ghost">Settings</span><span class="ui-btn is-destructive">Settings</span><span class="ui-btn is-primary" style="opacity:.45">Settings</span></div>
        <div class="ds-f2c-row">
          <span class="ui-field"><span>Label <b>*</b></span><small>This is a description</small><span class="ui-input" style="color:var(--muted-fg)">Placeholder text</span></span>
          <span class="ui-field"><span>Label <b>*</b></span><small>This is a description</small><span class="ui-input is-focus">Placeholder text</span></span>
          <span class="ui-field"><span>Label <b>*</b></span><small>This is a description</small><span class="ui-input is-error">Placeholder text</span><small class="ui-err">A note is required.</small></span>
        </div>
        <div class="ds-f2c-row"><span class="ui-badge r-success">Delivered</span><span class="ui-badge r-warning">Delayed</span><span class="ui-badge r-destructive">Failed</span><span class="ui-badge r-info">On the road</span><span class="ui-badge r-primary">Today</span></div>
        <div class="ds-f2c-row"><span class="ui-alert r-warning"><strong>Delayed</strong><span>Running 25 minutes late at Harbour depot.</span></span><span class="ui-alert r-info"><strong>On the road</strong><span>Next stop in 12 minutes.</span></span></div>
        <div class="ui-pages"><span>1</span><span class="is-on">2</span><span>3</span><span>…</span><span style="opacity:.4">10</span></div>
      </div>`).join("");
    codeSide.querySelectorAll(".ds-f2c-pane").forEach((p) => {
      const t = theme(brand, p.dataset.mode);
      if (p.dataset.mode === "dark") { t["--primary-fg"] = "#fafafa"; t["--destructive-text"] = SCALES.dark.red["600"]; }
      apply(p, t);
      p.querySelectorAll(".ui-btn.is-destructive").forEach((b) => (b.style.color = p.dataset.mode === "dark" ? "#09090b" : "#fafafa"));
    });
    const stage = document.getElementById("f2c-stage");
    document.querySelectorAll('input[name="f2c"]').forEach((r) => r.addEventListener("change", () => { stage.dataset.show = r.value; }));
  }

  /* ---------- 01.3: three layers, exploded; the top plane wears the current brand ---------- */
  const layers = document.getElementById("layers");
  if (layers) {
    layers.innerHTML = `
      <ol class="ds-stack-legend">
        <li><h4>Customer <span>their brand</span></h4><ul><li><code>colour</code></li><li><code>font</code></li><li><code>button shape</code></li></ul></li>
        <li><h4>Product <span>only what it needs</span></h4><ul><li><code>--menu-highlight: mix(--hover, --active)</code></li><li><code>--card (dark)</code></li></ul></li>
        <li><h4>Shared package <span>every product</span></h4><ul><li><code>scales 50–700</code></li><li><code>--success</code></li><li><code>--warning-text</code></li><li><code>--radius</code></li><li><code>Button</code></li><li><code>Input</code></li></ul></li>
      </ol>
      <div class="ds-iso" aria-hidden="true">
        <div class="ds-plane is-shared"><span class="ds-plane-n">Shared</span><span class="ui" data-btn="base"><span class="ui-btn is-primary">New run</span></span></div>
        <div class="ds-plane is-product"><span class="ds-plane-n">Product</span><span class="ds-mini-menu"><span>Rename</span><span class="is-hl">Duplicate</span><span>Archive</span></span></div>
        <div class="ds-plane is-customer"><span class="ds-plane-n" data-cname></span><span class="ui" data-btn="cust"><span class="ui-btn is-primary">New run</span></span></div>
      </div>`;
    const base = layers.querySelector('[data-btn="base"]');
    apply(base, theme(CUSTOMERS[1].colour, "light"));
    const cust = layers.querySelector('[data-btn="cust"]');
    listeners.push((c) => {
      const t = theme(c.colour, "light");
      cust.style.setProperty("--primary", pickPage(c.colour) === INK ? INK : NEAR_WHITE);
      cust.style.setProperty("--primary-fg", c.colour);
      cust.style.setProperty("--font", c.font); cust.style.setProperty("--btn-r", c.btn);
      layers.querySelector("[data-cname]").textContent = c.name;
      void t;
    });
  }

  /* ---------- 02.1: a wall of the scales ---------- */
  const wall = document.getElementById("wall");
  if (wall) {
    const L = SCALES.light;
    const cell = (h, st) => {
      const c = L[h][st];
      if (st === "600") return `<div class="ds-wall-c" style="background:${c};color:#fff"><small>on white</small><span>${ratio(c, "#ffffff").toFixed(1)}</span></div>`;
      if (st === "700") return `<div class="ds-wall-c" style="background:${c};color:${L[h]["50"]}"><small>on its 50</small><span>${ratio(c, L[h]["50"]).toFixed(1)}</span></div>`;
      return `<div class="ds-wall-c" style="background:${c}"><span class="sr-only">${h} ${st}</span></div>`;
    };
    wall.innerHTML = `<div class="ds-wall-grid" role="table" aria-label="Six roles, five steps, each step with one job">
      <div role="row" class="ds-wall-row"><div class="ds-wall-h" role="columnheader"><span class="sr-only">Role</span></div>${STEPS.map(([st, job]) => `<div class="ds-wall-h" role="columnheader"><b>${job}</b>${st}</div>`).join("")}</div>
      ${HUES.map(([h, name, role]) => `<div role="row" class="ds-wall-row"><div class="ds-wall-role" role="rowheader"><b>${role}</b><span>${name.toLowerCase()}</span></div>${STEPS.map(([st]) => cell(h, st)).join("")}</div>`).join("")}
    </div>`;
  }

  /* ---------- 02.2: lightness chart (on the dark sheet) ---------- */
  const chart = document.getElementById("light-chart");
  if (chart) {
    const W = 760, left = 150, right = 20, rowH = 42, top = 14, x0 = 0.4, x1 = 1.0;
    const rows = [["50", "Surface"], ["200", "Border"], ["500", "Charts, icons"], ["600", "Text on white"], ["700", "Text on a tint"]];
    const H = top + rows.length * rowH + 34;
    const X = (l) => left + ((l - x0) / (x1 - x0)) * (W - left - right);
    const order = ["brand", "blue", "green", "red", "purple", "amber"];
    let g = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Lightness of each step on six hues. Text on white sits between 0.50 and 0.54; text on a tint between 0.44 and 0.48.">`;
    rows.forEach(([st, job], i) => {
      const y = top + i * rowH + rowH / 2;
      const ls = Object.values(REAL_L[st]);
      const mn = Math.min(...ls), mx = Math.max(...ls);
      g += `<text class="row-l" x="0" y="${y + 4}">${job}</text><text class="lbl" x="${left - 12}" y="${y + 4}" text-anchor="end">${st}</text>`;
      g += `<line class="ax" x1="${left}" x2="${W - right}" y1="${y}" y2="${y}"/>`;
      g += `<rect class="band" x="${X(mn) - 11}" y="${y - 16}" width="${X(mx) - X(mn) + 22}" height="32" rx="16"/>`;
      order.filter((h) => REAL_L[st][h] != null).forEach((h, j, arr) => {
        const dy = (j - (arr.length - 1) / 2) * 4.4;
        g += `<circle cx="${X(REAL_L[st][h]).toFixed(1)}" cy="${(y + dy).toFixed(1)}" r="6.5" fill="${SCALES.light[h][st]}"><title>${h} ${st}: L ${REAL_L[st][h]}</title></circle>`;
      });
    });
    const yA = top + rows.length * rowH + 8;
    [0.4, 0.5, 0.6, 0.7, 0.8, 0.9, 1.0].forEach((v) => { g += `<g class="tick"><line class="ax" x1="${X(v)}" x2="${X(v)}" y1="${yA - 4}" y2="${yA + 2}"/><text x="${X(v)}" y="${yA + 18}" text-anchor="middle">${v.toFixed(1)}</text></g>`; });
    g += `<text class="lbl" x="0" y="${yA + 18}">OKLCH lightness</text></svg>`;
    chart.innerHTML = g;
  }

  /* ---------- 02.3: one specimen, light and dark, split by a slider ---------- */
  const split = document.getElementById("split");
  if (split) {
    const layer = (mode) => {
      const S = SCALES[mode], bg = NEUTRAL[mode].card;
      return `<div class="ds-split-layer is-${mode}" ${mode === "dark" ? 'aria-hidden="true"' : ""}><div class="ds-split-h"><span>${mode === "light" ? "Light" : "Dark"}</span><span>border · text · text on a tint</span></div>
        ${HUES.map(([h, name]) => `<div class="ds-split-row"><span>${name}</span>
          <i class="is-border" style="--c:${S[h]["200"]}"><span class="sr-only">border</span></i>
          <i style="color:${S[h]["600"]}">Aa <small>${ratio(S[h]["600"], bg).toFixed(1)}</small></i>
          <i style="background:${S[h]["50"]};color:${S[h]["700"]}">Aa <small>${ratio(S[h]["700"], S[h]["50"]).toFixed(1)}</small></i></div>`).join("")}</div>`;
    };
    split.innerHTML = `<div class="ds-split-stage" id="split-stage">${layer("light")}${layer("dark")}<span class="ds-split-handle"></span></div>
      <input type="range" id="split-range" min="0" max="100" value="50" aria-label="Move between the light and dark versions of the same specimen">
      <div class="ds-split-legend"><span>Light</span><span>Dark</span></div>`;
    const stage = split.querySelector("#split-stage");
    split.querySelector("#split-range").addEventListener("input", (e) => stage.style.setProperty("--split", `${e.target.value}%`));
  }

  /* ---------- 02.4: a customer's colour, passed through or derived ---------- */
  const cc = document.getElementById("cc");
  if (cc) {
    const COLOURS = { yellow: ["Pale yellow", "#fff29a"], navy: ["Navy", "#1d2b5c"] };
    cc.innerHTML = `
      <div class="cc-top">
        <div class="ds-seg" role="radiogroup" aria-label="Customer colour">
          <label><input type="radio" name="cc-colour" id="cc-yellow" value="yellow" checked><span class="tp-swatch" style="background:#fff29a"></span>Pale yellow</label>
          <label><input type="radio" name="cc-colour" id="cc-navy" value="navy"><span class="tp-swatch" style="background:#1d2b5c"></span>Navy</label>
        </div>
        <div class="ds-seg" role="radiogroup" aria-label="Rule">
          <label><input type="radio" name="cc-rule" id="cc-pass" value="passed">Passed through</label>
          <label><input type="radio" name="cc-rule" id="cc-derived" value="derived" checked>Derived</label>
        </div>
      </div>
      <div class="cc-modes" id="cc-modes"></div>`;
    const out = cc.querySelector("#cc-modes");
    const render = () => {
      const [, hex] = COLOURS[cc.querySelector('input[name="cc-colour"]:checked').value];
      const rule = cc.querySelector('input[name="cc-rule"]:checked').value;
      out.innerHTML = ["light", "dark"].map((mode) => `<div class="cc-pane ui" data-mode="${mode}">
          <span class="ds-label">${mode === "light" ? "Light" : "Dark"}</span>
          <div class="cc-line"><span class="ui-btn is-primary" style="display:inline-block">New run</span><span data-r="btn"></span></div>
          <div class="cc-line"><a class="ui-link" href="#customer-colour">View all runs</a><span data-r="link"></span></div>
          <div class="cc-line"><span class="ui-badge r-primary">Today</span><span data-r="tab"></span></div>
        </div>`).join("");
      out.querySelectorAll(".cc-pane").forEach((p) => {
        const t = theme(hex, p.dataset.mode, rule);
        apply(p, t);
        p.style.colorScheme = p.dataset.mode;
        const set = (k, r) => { p.querySelector(`[data-r="${k}"]`).innerHTML = chip(r); };
        set("btn", ratio(t["--primary-fg"], t["--primary"]));
        set("link", ratio(t["--primary-text"], t["--card"]));
        set("tab", ratio(t["--primary-container-fg"], t["--primary-container"]));
      });
    };
    cc.addEventListener("change", render);
    render();
  }

  /* ---------- contents: mark the card in view ---------- */
  const toc = document.querySelector(".cf-toc");
  if (toc) {
    const links = [...toc.querySelectorAll("a[href^='#']")];
    const ids = links.map((a) => a.getAttribute("href").slice(1)).filter((id) => id !== "top");
    let raf = 0;
    const update = () => {
      raf = 0;
      const line = innerHeight * 0.4;
      let cur = null;
      for (const id of ids) { const el = document.getElementById(id); if (el && el.getBoundingClientRect().top <= line) cur = id; }
      links.forEach((a) => a.removeAttribute("aria-current"));
      const at = links.find((a) => a.getAttribute("href") === `#${cur ?? "top"}`);
      if (at) at.setAttribute("aria-current", "step");
      toc.querySelectorAll(".cf-toc-part").forEach((li) => li.dataset.active = String(!!cur && !!li.querySelector(`a[href="#${cur}"]`)));
    };
    addEventListener("scroll", () => { if (!raf) raf = requestAnimationFrame(update); }, { passive: true });
    addEventListener("resize", () => { if (!raf) raf = requestAnimationFrame(update); });
    update();
  }

  /* ---------- review: theme switch ---------- */
  const bar = document.querySelector(".proto-bar");
  if (bar) {
    const set = (v) => {
      if (v === "system") document.documentElement.removeAttribute("data-theme"); else document.documentElement.setAttribute("data-theme", v);
      bar.querySelectorAll("button").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.themeSet === v)));
    };
    bar.addEventListener("click", (e) => { const b = e.target.closest("button"); if (b) set(b.dataset.themeSet); });
  }

  setCustomer("courier");
})();
